def solve(input):
    s = input

    # Two pointer approach with offset
    i, j, k = 0, 1, 0

    while i + k < len(s) and j + k < len(s):
        # When same character occurs at offset k
        if s[i + k] == s[j + k]:
            k += 1
        else:
            # Move the pointer that points to smaller character
            if s[i + k] < s[j + k]: 
                i += k + 1
            else:
                j += k + 1

            # Ensure i and j don't point to same position
            if i == j:
                j += 1
            k = 0

    # Return suffix starting from position i
    return s[i:]
