                found = True
                digit_value = int(s[i].c)

                # Calculate new position with current string length
                n = len(s)
                new_pos = (i - digit_value) % n

                # Remove from current position
                wrapper = s.pop(i)
                # Insert at target position
                s.insert(new_pos, wrapper)
                # Mark as moved
                wrapper.moved = True

                break

        if not found:
            break

    return ''.join(w.c for w in s)
