def solve(input):
    s = input
    n = len(s)
    result = []

    # Precompute max ASCII values to the left of each position
    max_left = [0] * n
    for i in range(1, n):
        max_left[i] = max(max_left[i-1], ord(s[i-1]))

    # Precompute max ASCII values to the right of each position
    max_right = [0] * n
    for i in range(n-2, -1, -1):
        max_right[i] = max(max_right[i+1], ord(s[i+1]))

    # Calculate depth for each position
    for i in range(n):
        current_height = ord(s[i])
        depth = min(max_left[i], max_right[i]) - current_height

        # Clamp depth to [0, 9]
        if depth <= 0:
            result.append('0')
        elif depth > 9:
            result.append('9')
        else:
            result.append(str(depth))

    return ''.join(result)
