def solve(input):
    n = str(input)

    # Repeat until length >= 15
    if len(n) < 15:
        times = (15 + len(n) - 1) // len(n)  # ceiling division
        repeated = n * times
    else:
        repeated = n

    # Map each digit to a letter
    result = []
    for char in repeated:
        digit = int(char)
        if digit % 2 == 0:
            # Even: 0→a, 2→b, 4→c, 6→d, 8→e
            result.append(chr(ord('a') + digit // 2))
        else:
            # Odd: 1→v, 3→w, 5→x, 7→y, 9→z
            result.append(chr(ord('v') + (digit - 1) // 2))

    return ''.join(result)
