    # Interleave the two halves
    result = []
    i = 0
    while i < len(first_half) or i < len(second_half_reversed):
        if i < len(first_half):
            result.append(first_half[i])
        if i < len(second_half_reversed):
            result.append(second_half_reversed[i])
