    pivot = -1
    for i in range(n - 2, -1, -1):
        if s[i] < s[i + 1]:
            pivot = i
            break

    # Step 2: If no pivot exists, reverse entire string
    if pivot == -1:
        s.reverse()
        return ''.join(s)

    # Step 3 & 4: Find the rightmost character greater than pivot and swap
    for i in range(n - 1, pivot, -1):
        if s[i] > s[pivot]:
            s[pivot], s[i] = s[i], s[pivot]
            break

    # Step 5: Reverse the substring after the original pivot position
    s[pivot + 1:] = reversed(s[pivot + 1:])

    return ''.join(s)
