def solve(input):
    s = input

    if not s:
        return ""

    # Step 1 & 2: Identify runs and record character and length
    runs = []
    current_char = s[0]
    current_length = 1

    for i in range(1, len(s)):
        if s[i] == current_char:
            current_length += 1
        else:
            runs.append((current_char, current_length))
            current_char = s[i]
            current_length = 1
    runs.append((current_char, current_length))

    # Step 3: Extract characters and lengths separately
    characters = [char for char, length in runs]
    lengths = [length for char, length in runs]

    # Step 4: Reverse only the list of run lengths
    reversed_lengths = lengths[::-1]

    # Step 5: Reconstruct the string
    result = ""
    for char, length in zip(characters, reversed_lengths):
        result += char * length

    return result
